@app.get("/api/v1/sync/tasks/{task_id}/result")
async def get_sync_task_result(
    task_id: str,
    request: Request,
    current_user: User = Depends(get_current_user)
):
    sync_registry: TaskRegistry = request.app.state.sync_registry
    task_data = await sync_registry.get_task(task_id)
    if not task_data or task_data.initiator_user_id != current_user.id:
        raise HTTPException(status_code=404, detail="Task not found or access denied")
    return {
        "task_id": task_id,
        "status": task_data.status,
        "synced_records": task_data.record_count,
        "destination_target": task_data.destination_target
    }
